<?php $title='Mitteilungen'; ?>
<div class="page-header split"><div><p class="eyebrow">Mitteilungen</p><h1>Interne Mitteilungen</h1><p>Aktuell gültige Informationen für Ihren Standort und Ihre Rolle.</p></div><?php if(can('messages.manage')):?><a class="button ghost" href="<?= e(url('announcements/manage')) ?>">Verwalten</a><?php endif;?></div>
